
'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { useForm, useFieldArray } from 'react-hook-form';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { useDoc, useFirestore, useMemoFirebase } from '@/firebase';
import { doc, setDoc } from 'firebase/firestore';
import { useToast } from '@/hooks/use-toast';
import { useEffect, useState } from 'react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from '@/components/ui/card';
import { PlusCircle, Trash2, UploadCloud } from 'lucide-react';
import { setDocumentNonBlocking } from '@/firebase/non-blocking-updates';
import { Skeleton } from '@/components/ui/skeleton';


const linkSchema = z.object({
  label: z.string().min(1, 'Label is required'),
  value: z.string().min(1, 'Value is required'),
  href: z.string().url('Must be a valid URL'),
});

const socialSchema = z.object({
  label: z.string().min(1, 'Label is required'),
  href: z.string().url('Must be a valid URL'),
});

const contactFormSchema = z.object({
  avatarUrl: z.string().url('Must be a valid URL'),
  name: z.string().min(2, 'Name must be at least 2 characters'),
  title: z.string().min(2, 'Title must be at least 2 characters'),
  email: z.string().email('Please enter a valid email'),
  whatsapp: z.string().min(10, 'Enter a valid phone number'),
  links: z.array(linkSchema).optional(),
  socials: z.array(socialSchema).optional(),
});

type ContactFormValues = z.infer<typeof contactFormSchema>;

const defaultContactData: ContactFormValues = {
    avatarUrl: 'https://picsum.photos/seed/hicham/200/200',
    name: 'Hicham Eljabbary',
    title: 'Motion Graphics Designer',
    email: 'hicham@gmail.com',
    whatsapp: '+212 619 665 220',
    links: [
        { label: 'Behance', value: '@BeLofted', href: '#' },
        { label: 'LinkedIn', value: 'Hicham Eljabbary', href: '#' },
        { label: 'Fiverr', value: '@BeLofted', href: '#' },
    ],
    socials: [
        { label: 'Instagram', href: '#' },
        { label: 'Facebook', href: '#' },
        { label: 'Twitter', href: '#' },
    ]
};

export function ContactAdmin() {
  const { toast } = useToast();
  const firestore = useFirestore();
  
  const contactDetailsRef = useMemoFirebase(
    () => (firestore ? doc(firestore, 'contact/details') : null),
    [firestore]
  );
  
  const { data: contactData, isLoading, error } = useDoc<ContactFormValues>(contactDetailsRef);
  
  const form = useForm<ContactFormValues>({
    resolver: zodResolver(contactFormSchema),
    defaultValues: contactData || defaultContactData,
  });

  const { fields: linkFields, append: appendLink, remove: removeLink } = useFieldArray({
    control: form.control,
    name: "links",
  });

  const { fields: socialFields, append: appendSocial, remove: removeSocial } = useFieldArray({
    control: form.control,
    name: "socials",
  });

  useEffect(() => {
    if (contactData) {
      form.reset(contactData);
    }
  }, [contactData, form]);

  const onSubmit = (values: ContactFormValues) => {
    if (!contactDetailsRef) return;
    setDocumentNonBlocking(contactDetailsRef, values, {});
    toast({
      title: 'Contact Info Saved',
      description: 'Your contact page details have been updated.',
    });
  };

  const handleSeedData = async () => {
    if (!contactDetailsRef) return;
    try {
        await setDoc(contactDetailsRef, defaultContactData);
        toast({ title: "Seeded!", description: "Default contact info has been saved."});
    } catch(e: any) {
        toast({ variant: 'destructive', title: "Error", description: e.message });
    }
  }
  
  if (isLoading) {
    return (
        <ScrollArea className="h-full">
            <div className="p-4 md:p-6 grid gap-6">
                <Card>
                    <CardHeader>
                        <Skeleton className="h-6 w-1/2" />
                        <Skeleton className="h-4 w-3/4" />
                    </CardHeader>
                    <CardContent className="space-y-4">
                        {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-10 w-full" />)}
                    </CardContent>
                </Card>
                 <Card>
                    <CardHeader>
                        <Skeleton className="h-6 w-1/2" />
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <Skeleton className="h-24 w-full" />
                        <Skeleton className="h-10 w-24" />
                    </CardContent>
                </Card>
            </div>
        </ScrollArea>
    )
  }

  if (error && !contactData) {
     return (
      <div className="flex flex-col items-center justify-center h-full gap-4">
        <p className="text-destructive">Could not load contact information.</p>
        <Button onClick={handleSeedData}>
          <UploadCloud className="mr-2 h-4 w-4" />
          Initialize Contact Data
        </Button>
      </div>
    );
  }

  return (
    <ScrollArea className="h-[calc(100vh-250px)]">
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="p-1 md:p-6 grid gap-6">
          <Card>
            <CardHeader>
              <CardTitle>Personal Information</CardTitle>
              <CardDescription>Update your personal details displayed on the contact page.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <FormField name="avatarUrl" control={form.control} render={({ field }) => (
                <FormItem>
                  <FormLabel>Avatar URL</FormLabel>
                  <FormControl><Input {...field} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
              <FormField name="name" control={form.control} render={({ field }) => (
                <FormItem>
                  <FormLabel>Name</FormLabel>
                  <FormControl><Input {...field} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
              <FormField name="title" control={form.control} render={({ field }) => (
                <FormItem>
                  <FormLabel>Title / Role</FormLabel>
                  <FormControl><Input {...field} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
              <FormField name="email" control={form.control} render={({ field }) => (
                <FormItem>
                  <FormLabel>Contact Email</FormLabel>
                  <FormControl><Input {...field} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
              <FormField name="whatsapp" control={form.control} render={({ field }) => (
                <FormItem>
                  <FormLabel>WhatsApp Number</FormLabel>
                  <FormControl><Input {...field} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Professional Links</CardTitle>
              <CardDescription>Links to sites like Behance, LinkedIn, Fiverr, etc.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {linkFields.map((field, index) => (
                <div key={field.id} className="flex gap-4 items-end p-2 border rounded-lg">
                  <FormField name={`links.${index}.label`} control={form.control} render={({ field }) => (
                    <FormItem className="flex-1"><FormLabel>Label</FormLabel><FormControl><Input {...field} /></FormControl><FormMessage /></FormItem>
                  )} />
                  <FormField name={`links.${index}.value`} control={form.control} render={({ field }) => (
                    <FormItem className="flex-1"><FormLabel>Value</FormLabel><FormControl><Input {...field} /></FormControl><FormMessage /></FormItem>
                  )} />
                  <FormField name={`links.${index}.href`} control={form.control} render={({ field }) => (
                    <FormItem className="flex-1"><FormLabel>URL</FormLabel><FormControl><Input {...field} /></FormControl><FormMessage /></FormItem>
                  )} />
                  <Button type="button" variant="destructive" size="icon" onClick={() => removeLink(index)}><Trash2 className="h-4 w-4" /></Button>
                </div>
              ))}
               <Button type="button" variant="outline" size="sm" onClick={() => appendLink({ label: '', value: '', href: '' })}>
                <PlusCircle className="mr-2 h-4 w-4" /> Add Link
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Social Media</CardTitle>
              <CardDescription>Links to your social media profiles like Instagram, Facebook, etc.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {socialFields.map((field, index) => (
                <div key={field.id} className="flex gap-4 items-end p-2 border rounded-lg">
                  <FormField name={`socials.${index}.label`} control={form.control} render={({ field }) => (
                    <FormItem className="flex-1"><FormLabel>Label</FormLabel><FormControl><Input {...field} placeholder="e.g. Instagram" /></FormControl><FormMessage /></FormItem>
                  )} />
                  <FormField name={`socials.${index}.href`} control={form.control} render={({ field }) => (
                    <FormItem className="flex-1"><FormLabel>URL</FormLabel><FormControl><Input {...field} /></FormControl><FormMessage /></FormItem>
                  )} />
                  <Button type="button" variant="destructive" size="icon" onClick={() => removeSocial(index)}><Trash2 className="h-4 w-4" /></Button>
                </div>
              ))}
               <Button type="button" variant="outline" size="sm" onClick={() => appendSocial({ label: '', href: '' })}>
                <PlusCircle className="mr-2 h-4 w-4" /> Add Social
              </Button>
            </CardContent>
            <CardFooter>
              <Button type="submit">Save Changes</Button>
            </CardFooter>
          </Card>
        </form>
      </Form>
    </ScrollArea>
  );
}
